<?php
declare(strict_types=1);
const DB_HOST='127.0.0.1'; const DB_PORT=3306; const DB_NAME='bankease'; const DB_USER='root'; const DB_PASS=''; const BASE_URL='/BankEase_Admin';
date_default_timezone_set('Asia/Dhaka');
if(session_status()!==PHP_SESSION_ACTIVE){session_name('BANKEASE_ADMIN');session_start();}
function db():PDO{static $p=null;if(!$p)$p=new PDO('mysql:host='.DB_HOST.';port='.DB_PORT.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);return $p;}
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function url(string $s=''):string{return BASE_URL.($s?'/'.ltrim($s,'/'):'' );}
function go(string $s):never{header('Location: '.url($s));exit;}
function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return '<input type="hidden" name="_csrf" value="'.e($_SESSION['csrf']).'">';}
function verify_csrf():void{if(!hash_equals($_SESSION['csrf']??'',$_POST['_csrf']??'')){http_response_code(400);exit('Invalid form token. Reload and retry.');}}
function flash(?string $m=null,string $kind='ok'):?array{if($m!==null){$_SESSION['flash']=[$m,$kind];return null;}$f=$_SESSION['flash']??null;unset($_SESSION['flash']);return $f;}
function user():?array{return $_SESSION['admin_user']??null;}
function require_staff():array{$u=user();if(!$u||!in_array($u['role'],['Administrator','Employee'],true))go('login.php');return $u;}
function require_admin():array{$u=require_staff();if($u['role']!=='Administrator'){http_response_code(403);exit('Administrator permission required.');}return $u;}
function branch_scope(string $alias='b'):string{$u=require_staff();return $u['role']==='Administrator'?'':" AND {$alias}.branch_id=".(int)$u['branch_id'];}
function audit(string $action,string $table,?int $id,string $desc):void{db()->prepare("INSERT INTO audit_logs(user_id,action,target_table,target_id,description,ip_address,result) VALUES(?,?,?,?,?,?, 'success')")->execute([user()['id']??null,$action,$table,$id,$desc,$_SERVER['REMOTE_ADDR']??null]);}
function page_start(string $title):void{$u=user();$f=flash();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · BankEase Staff</title><link rel="stylesheet" href="<?=e(url('assets/admin.css'))?>"><link rel="stylesheet" href="<?=e(url('assets/profile.css'))?>"></head><body><header class="bar"><a class="brand" href="<?=e(url('dashboard.php'))?>"><i>B</i>BankEase <span>STAFF PORTAL</span></a><div class="bar-right"><?php if($u):$ns=db()->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0');$ns->execute([$u['id']]);$un=(int)$ns->fetchColumn();?><a href="<?=e(url('module.php?view=notifications'))?>">🔔 Notifications <b><?=e($un)?></b></a><span><?=e($u['name'])?> · <?=e($u['role'])?></span><a class="button yellow small" href="<?=e(url('logout.php'))?>">Log out</a><?php endif;?></div></header><?php if($u):?><div class="shell"><aside class="side"><div class="side-label">WORKSPACE</div><?php $links=['dashboard.php'=>'Dashboard','module.php?view=approvals'=>'Approvals','module.php?view=notifications'=>'Notifications','module.php?view=new_customer'=>'New Customer','module.php?view=customers'=>'Customer List','module.php?view=new_account'=>'New Account','module.php?view=accounts'=>'Account List','module.php?view=cards'=>'Cards','module.php?view=deposit'=>'Deposit','module.php?view=withdraw'=>'Withdraw','module.php?view=transfer'=>'Transfer','module.php?view=transactions'=>'Transaction History','module.php?view=loans'=>'Loan Management','module.php?view=reports'=>'Reports','module.php?view=password'=>'Change Password'];if($u['role']==='Administrator')$links+=['module.php?view=branches'=>'Branch Management','module.php?view=employees'=>'Employee Management','module.php?view=account_types'=>'Account Types','module.php?view=settings'=>'User Settings','module.php?view=audit'=>'Audit Log'];foreach($links as $href=>$label):?><a href="<?=e(url($href))?>"><?=e($label)?></a><?php endforeach;?></aside><main class="main"><?php if($f):?><div class="notice <?=e($f[1])?>"><?=e($f[0])?></div><?php endif;?><?php else:?><main class="login-main"><?php endif;?><?php }
function page_end():void{?></main><?php if(user()):?></div><?php endif;?><footer>BankEase Admin · Local demonstration portal</footer></body></html><?php }
